#include <iostream>

class Counter {
private:
    int value;
public:
    Counter(int start) : value(start) {}
    void add(int delta) { value += delta; }
    int get() const { return value; }
};

int main() {
    Counter c(10);
    c.add(5);
    std::cout << c.get() << \"\n\";
    return 0;
}

