#include <iostream>

class Wallet {
private:
    int balance;
public:
    Wallet(int start) : balance(start >= 0 ? start : 0) {}
    void deposit(int amount) { if (amount > 0) balance += amount; }
    int getBalance() const { return balance; }
};

int main() {
    Wallet w(1000);
    w.deposit(250);
    std::cout << w.getBalance() << \"\n\";
    return 0;
}

